package com.secman.controller

import com.secman.dto.*
import com.secman.service.*
import io.micronaut.core.annotation.Nullable
import io.micronaut.http.HttpResponse
import io.micronaut.http.annotation.*
import io.micronaut.scheduling.TaskExecutors
import io.micronaut.scheduling.annotation.ExecuteOn
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication
import io.micronaut.security.rules.SecurityRule

@Controller("/api/integrations/v1")
@Secured(SecurityRule.IS_AUTHENTICATED)
@ExecuteOn(TaskExecutors.BLOCKING)
open class IntegrationController(
    private val admin: IntegrationAdminService,
    private val reads: IntegrationReadService,
    private val scans: IntegrationScanService,
    private val health: IntegrationHealthNotifier
) {
    @Get("/scanners")
    open fun scanners(authentication: Authentication) = reads.scanners(authentication)

    @Post("/scanners")
    @Secured("ADMIN")
    open fun createScanner(@Body request: IntegrationScannerRequest, authentication: Authentication) =
        admin.saveScanner(null, request, authentication)

    @Put("/scanners/{id}")
    @Secured("ADMIN")
    open fun updateScanner(@PathVariable id: Long, @Body request: IntegrationScannerRequest, authentication: Authentication) =
        admin.saveScanner(id, request, authentication)

    @Post("/scanners/{id}/subjects")
    @Secured("ADMIN")
    open fun bind(@PathVariable id: Long, @Body request: IntegrationSubjectRequest, authentication: Authentication) =
        reads.subject(admin.bind(id, request, authentication), authentication)

    @Get("/scanners/{id}/subjects")
    open fun subjects(@PathVariable id: Long, @QueryValue(defaultValue = "0") page: Int,
                      @QueryValue(defaultValue = "100") size: Int, authentication: Authentication) =
        reads.subjects(id, page, size, authentication)

    @Post("/runs")
    open fun submit(@Body request: IntegrationRunRequest, authentication: Authentication) =
        scans.submit(request, authentication).also(health::completed)

    @Get("/summary")
    open fun summary(authentication: Authentication) = reads.summary(authentication)

    @Get("/runs/{id}")
    open fun run(@PathVariable id: Long, authentication: Authentication) = reads.run(id, authentication)

    @Get("/runs")
    open fun runs(@QueryValue(defaultValue = "0") page: Int, @QueryValue(defaultValue = "100") size: Int,
                  @Nullable @QueryValue scannerId: Long?, @Nullable @QueryValue subjectId: Long?, authentication: Authentication) =
        reads.runs(page, size, scannerId, subjectId, authentication)

    @Get("/findings")
    open fun findings(@QueryValue(defaultValue = "0") page: Int, @QueryValue(defaultValue = "100") size: Int,
                      @Nullable @QueryValue scannerId: Long?, @Nullable @QueryValue subjectId: Long?,
                      @Nullable @QueryValue githubRepositoryId: Long?, @Nullable @QueryValue source: String?,
                      @Nullable @QueryValue owner: String?, @Nullable @QueryValue severity: String?,
                      @Nullable @QueryValue state: String?, @Nullable @QueryValue search: String?, authentication: Authentication) =
        reads.findings(page, size, IntegrationFindingFilter(scannerId, subjectId, githubRepositoryId, source, owner, severity, state, search), authentication)

    @Get("/findings/{id}")
    open fun finding(@PathVariable id: Long, authentication: Authentication) = reads.finding(id, authentication)

    @Get("/findings/{id}/attachments/{attachmentId}")
    open fun attachment(@PathVariable id: Long, @PathVariable attachmentId: Long, authentication: Authentication): HttpResponse<ByteArray> {
        val attachment = reads.attachment(id, attachmentId, authentication)
        return HttpResponse.ok(attachment.content).contentType(attachment.contentType)
            .header("X-Content-Type-Options", "nosniff")
            .header("Content-Disposition", "attachment; filename=\"" + attachment.fileName + "\"")
            .header("Cache-Control", "private, no-store")
    }
}
     * Query Parameters:
     * - severity: Optional CVSS severity filter (e.g., "Critical", "High", "Medium", "Low")
     * - system: Optional system/asset name filter (substring match, case-insensitive)
     * - exceptionStatus: Optional filter - "excepted", "not_excepted", or omit for all
     * - product: Optional product/version filter (substring match, case-insensitive)
     * - cve: Optional CVE/vulnerability ID filter (substring match, case-insensitive)
     * - adDomain: Optional AD domain filter (substring match, case-insensitive)
     * - cloudAccountId: Optional AWS cloud account ID filter (substring match, case-insensitive)
     * - page: Page number (0-indexed, default: 0)
     * - size: Page size (default: 50, max: 500)
     * - sort: Sort field (e.g., "assetName", "cvssSeverity", "scanTimestamp", "vulnerabilityId", "vulnerableProductVersions", "daysOpen")
     * - sortDir: Sort direction ("asc" or "desc", default: "desc")
     */
    @Get("/api/vulnerabilities/current")
    @Secured("ADMIN", "VULN", "SECCHAMPION")
    open fun getCurrentVulnerabilities(
        authentication: Authentication,
        @Nullable @QueryValue severity: String?,
        @Nullable @QueryValue system: String?,
        @Nullable @QueryValue exceptionStatus: String?,
        @Nullable @QueryValue product: String?,
        @Nullable @QueryValue cve: String?,
        @Nullable @QueryValue adDomain: String?,
        @Nullable @QueryValue cloudAccountId: String?,
        @Nullable @QueryValue page: Int?,
        @Nullable @QueryValue size: Int?,
        @Nullable @QueryValue sort: String?,
        @Nullable @QueryValue sortDir: String?,
        @Nullable @QueryValue knownTotal: Long?,
        @Nullable @QueryValue countMode: String?,
        /**
         * Opt back in to installer/setup payload findings ("Chrome Installer", "Photon Setup").
         * Default false: these are excluded from every list, count, export and statistic, and a
         * caller has to ask for them explicitly. Widens visibility of rows the caller is ALREADY
         * authorized to see — it never touches the accessible-asset scope.
         */
        @QueryValue(defaultValue = "false") includeInstallerFindings: Boolean
    ): HttpResponse<PaginatedVulnerabilitiesResponse> {
        return try {
            // Validate and sanitize pagination parameters.
            // Page is capped at 100_000 to bound the SQL OFFSET cost: an unbounded page
            // value lets a caller force MariaDB into a large sequential scan-and-discard
            // (e.g. ?page=10000000 → OFFSET 5_000_000_000). 100_000 is well past anything
            // legitimate pagination reaches given the table's row count and is cheap to enforce.
            val pageNumber = minOf(maxOf(page ?: 0, 0), 100_000)
            val pageSize = minOf(maxOf(size ?: 50, 1), 500)

            // Default to excluding excepted vulnerabilities when no filter specified
            val effectiveExceptionStatus = if (exceptionStatus.isNullOrBlank()) "not_excepted" else exceptionStatus

            log.debug("Getting current vulnerabilities for user: {} - severity: {}, system: {}, exceptionStatus: {} (effective: {}), product: {}, cve: {}, adDomain: {}, cloudAccountId: {}, page: {}, size: {}",
                authentication.name, severity, system, exceptionStatus, effectiveExceptionStatus, product, cve, adDomain, cloudAccountId, pageNumber, pageSize)

            // ADMIN and SECCHAMPION have universal access.
            val isAdmin = authentication.roles.contains("ADMIN") ||
                authentication.roles.contains("SECCHAMPION") ||
                authentication.roles.contains("ROLE_ADMIN") ||
                authentication.roles.contains("ROLE_SECCHAMPION")

            // Get accessible asset IDs (only needed for non-ADMIN users)
            // PERFORMANCE: For ADMIN users, we skip this query entirely.
            // For non-admins, AccessibleAssetIdsCache memoizes the answer per HTTP
            // request, so subsequent endpoints in the same request (badge poll,
            // count, list, exceptions) reuse one fan-out of access-control queries.
            val accessibleAssetIds = if (isAdmin) {
                emptySet()  // Not used for ADMIN
            } else {
                accessibleAssetIdsCache.get(authentication)
            }

            // PERFORMANCE OPTIMIZED: Use database-level pagination and access control
            log.error("Error during importTimestamp migration", e)
            HttpResponse.serverError<ErrorResponse>()
                .body(ErrorResponse("An internal error occurred"))
        }
    }

    /**
     * Add or update vulnerability via CLI
     *
     * POST /api/vulnerabilities/cli-add
     * Auth: ADMIN or VULN role
     * Request: AddVulnerabilityRequestDto
     * Response: AddVulnerabilityResponseDto (200 OK)
     *
     * Implements upsert pattern:
     * - If asset doesn't exist: create it with type=SERVER, owner=CLI-IMPORT
     * - If vulnerability with same CVE exists for asset: update it
     * - Otherwise: create new vulnerability
     *
     * User Story 1: Add vulnerability to existing asset (P1)
     * User Story 2: Add vulnerability with auto-created asset (P2)
     */
    @Post("/api/vulnerabilities/cli-add")
    @Secured("ADMIN", "VULN")
    open fun addVulnerabilityFromCli(
        @Valid @Body request: AddVulnerabilityRequestDto,
        authentication: Authentication
    ): HttpResponse<*> {
        return try {
            log.info("CLI add-vulnerability requested by user: {} - hostname: {}, cve: {}",
                authentication.name, request.hostname, request.cve)

            val result = vulnerabilityService.addVulnerabilityFromCli(request)

            log.info("CLI add-vulnerability completed: assetName={}, operation={}, assetCreated={}",
                result.assetName, result.operation, result.assetCreated)

            HttpResponse.ok(result)

        } catch (e: IllegalArgumentException) {
            log.warn("Invalid CLI add-vulnerability request: {}", e.message)
            HttpResponse.badRequest(ErrorResponse(e.message ?: "Invalid request"))
        } catch (e: Exception) {
            log.error("Error adding vulnerability via CLI", e)
            HttpResponse.serverError<ErrorResponse>()
                .body(ErrorResponse("An internal error occurred"))
        }
    }
}

