            ) from exc

    @staticmethod
    def _detail(response) -> str:
        try:
            payload = response.json()
        except Exception:  # noqa: BLE001
            return response.text[:200]
        if isinstance(payload, dict):
            return str(payload.get("error") or payload.get("message") or payload)[:200]
