class HttpUploader(_HttpxBacked):
    """Direct REST client for ``POST /api/vulnerabilities/cli-add``.

    Authenticates either with a JWT you already hold (``Authorization: Bearer``)
    or by logging in at ``/api/auth/login``, which returns the JWT in the
    ``secman_auth`` cookie that httpx then replays.
    """

    transport = "http"

    def __init__(
        self,
        base_url: str,
        *,
        token: str | None = None,
        username: str | None = None,
        REDACTED: str | None = None,
        **kwargs: Any,
    ) -> None:
        headers = {"Accept": "application/json"}
        if token:
            headers["Authorization"] = f"Bearer {token}"
        super().__init__(base_url, headers=headers, **kwargs)
        self.token = token
        self.username = username
        self.REDACTED = REDACTED

    @property
    def endpoint(self) -> str:
        return f"{self.base_url}/api/vulnerabilities/cli-add"

    def connect(self) -> None:
        if self.token or not self.username:
            return
        response = self._send(
            "POST",
            "/api/auth/login",
            json={"username": self.username, "REDACTED": self.REDACTED or ""},
        )
        if response.status_code >= 400:
            raise SecmanError(
                f"SecMan login failed (HTTP {response.status_code}): {self._detail(response)}"
            )
        payload = self._json(response)
        if isinstance(payload, dict) and payload.get("mfaRequired"):
            raise SecmanError(
                "SecMan requires MFA for this account. Use an automation account without "
                "MFA, or pass an existing JWT with --secman-token."
            )

    def existing_vulnerability_ids(
        self, hostnames: Iterable[str], id_prefix: str
    ) -> set[tuple[str, str]]:
        found: set[tuple[str, str]] = set()
        for hostname in sorted({h.lower() for h in hostnames}):
            for page in range(_MAX_PAGES):
                response = self._send(
                    "GET",
                    "/api/vulnerabilities/current",
                    params={
                        "system": hostname,
                        # Anything SecMan does not recognise here means "no exception
                        # filter"; the default is not_excepted, which would hide an
                        # excepted finding and make us upload it again.
                        "exceptionStatus": "all",
                        # Hidden installer rows still occupy the (asset, cve) slot.
                        "includeInstallerFindings": True,
                        "page": page,
                        "size": _PAGE_SIZE,
                    },
                )
                if response.status_code >= 400:
                    raise SecmanError(
                        f"Could not list existing vulnerabilities for {hostname} "
                        f"(HTTP {response.status_code}): {self._detail(response)}"
                    )
                payload = self._json(response)
                content = (payload or {}).get("content") or []
                for row in content:
                    if not isinstance(row, dict):
                        continue
                    # `system` is a substring match, so other hosts can come back.
                    name = str(row.get("assetName") or "").lower()
                    vuln_id = row.get("vulnerabilityId")
                    if name == hostname and vuln_id:
                        found.add((name, str(vuln_id)))
                if not payload.get("hasNext"):
                    break
        return found

    def upload(self, item: UploadItem, owner: str) -> tuple[str, str]:
        response = self._send(
            "POST", "/api/vulnerabilities/cli-add", json=item.payload(owner)
        )
        if response.status_code >= 400:
            raise SecmanError(
                f"HTTP {response.status_code}: {self._detail(response)}"
            )
        payload = self._json(response)
        if not isinstance(payload, dict):
            raise SecmanError(f"unexpected cli-add response: {str(payload)[:200]}")
        operation = str(payload.get("operation") or "").upper()
        status = "created" if operation == "CREATED" else "updated"
        return status, str(payload.get("message") or "")

    def register_asset(
        self, hostname: str, owner: str, uri: str, asset_type: str
    ) -> tuple[str, str]:
        """``PUT /api/assets/import`` — SecMan's idempotent upsert for scanners.

        It looks the asset up by name and merges, preserving operator-set fields,
        so re-running a scan never mints a second asset. It needs the ADMIN role;
        a 401/403 is reported per item rather than aborting the upload.
        """
        response = self._send(
            "PUT",
            "/api/assets/import",
            json={"name": hostname, "type": asset_type, "owner": owner, "uri": uri},
        )
        if response.status_code >= 400:
            raise SecmanError(
                f"HTTP {response.status_code}: {self._detail(response)}"
            )
        payload = self._json(response)
        if not isinstance(payload, dict):
            raise SecmanError(f"unexpected assets/import response: {str(payload)[:200]}")
        status = "created" if payload.get("created") else "updated"
        asset = payload.get("asset")
        detail = ""
        if isinstance(asset, dict):
            detail = f"asset id {asset.get('id')}"
        return status, detail

    def list_integration_subjects(self, scanner_id: int) -> list[dict[str, Any]]:
        subjects: list[dict[str, Any]] = []
        for page in range(_MAX_PAGES):
            response = self._send(
                "GET",
                f"/api/integrations/v1/scanners/{scanner_id}/subjects",
                params={"page": page, "size": 100},
            )
            if response.status_code >= 400:
                raise SecmanError(
                    f"Could not list integration subjects for scanner {scanner_id} "
                    f"(HTTP {response.status_code}): {self._detail(response)}"
                )
            payload = self._json(response)
            if not isinstance(payload, dict) or not isinstance(payload.get("content"), list):
                raise SecmanError("unexpected integration subject response")
            for row in payload["content"]:
                if not isinstance(row, dict):
                    raise SecmanError("integration subject response contains a non-object row")
                if row.get("scannerId") != scanner_id:
                    raise SecmanError("integration subject response crossed scanner scope")
                subjects.append(row)
            total_pages = payload.get("totalPages")
            if not isinstance(total_pages, int) or page + 1 >= total_pages:
                break
        return subjects

    def submit_integration_run(self, body: dict[str, Any]) -> dict[str, Any]:
        response = self._send("POST", "/api/integrations/v1/runs", json=body)
        if response.status_code >= 400:
            raise SecmanError(
                f"Integration run rejected (HTTP {response.status_code}): {self._detail(response)}"
            )
        payload = self._json(response)
        if not isinstance(payload, dict):
            raise SecmanError(f"unexpected integration run response: {str(payload)[:200]}")
        _validate_run_ack(body, payload)
        return payload


class McpUploader(_HttpxBacked):
    """JSON-RPC 2.0 client for SecMan's MCP endpoint.

    Authenticates with an MCP API key plus the delegated user's email; SecMan
    requires both headers on ``tools/call`` and computes effective permissions as
    ``api key permissions ∩ delegated user's role permissions``.
    """

    transport = "mcp"

    def __init__(
        self,
        base_url: str,
        *,
        api_key: str,
        user_email: str,
        **kwargs: Any,
    ) -> None:
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "X-MCP-API-Key": api_key,
            "X-MCP-User-Email": user_email,
        }
        super().__init__(base_url, headers=headers, **kwargs)
        self.user_email = user_email
        self._path = "/mcp" if not self.base_url.endswith("/mcp") else ""
        self._next_id = 0

    @property
    def endpoint(self) -> str:
        return f"{self.base_url}{self._path}"

    def _rpc(self, method: str, params: dict[str, Any] | None = None) -> Any:
        self._next_id += 1
        body: dict[str, Any] = {"jsonrpc": "2.0", "id": self._next_id, "method": method}
        if params is not None:
            body["params"] = params
        response = self._send("POST", self._path or "/", json=body)
        if response.status_code >= 400:
            raise SecmanError(
                f"MCP {method} failed (HTTP {response.status_code}): {self._detail(response)}"
            )
        payload = self._json(response)
        if not isinstance(payload, dict):
            raise SecmanError(f"MCP {method} returned {str(payload)[:200]}")
        error = payload.get("error")
        if error:
            message = error.get("message") if isinstance(error, dict) else error
            raise SecmanError(f"MCP {method} error: {message}")
        return payload.get("result")

    def _notify(self, method: str, params: dict[str, Any] | None = None) -> None:
        body: dict[str, Any] = {"jsonrpc": "2.0", "method": method}
        if params is not None:
            body["params"] = params
        self._send("POST", self._path or "/", json=body)

    def _call_tool(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        result = self._rpc("tools/call", {"name": name, "arguments": arguments})
        if not isinstance(result, dict):
            raise SecmanError(f"MCP tool {name} returned {str(result)[:200]}")
        if result.get("isError"):
            raise SecmanError(f"MCP tool {name} reported an error: {str(result)[:200]}")
        # SecMan serialises the tool's structured result into a single text block.
        for part in result.get("content") or []:
            if isinstance(part, dict) and part.get("type") == "text":
                try:
                    decoded = json.loads(part.get("text") or "")
                except json.JSONDecodeError as exc:
                    raise SecmanError(
                        f"MCP tool {name} returned unparseable content: {part.get('text', '')[:200]}"
                    ) from exc
                if isinstance(decoded, dict):
                    return decoded
        raise SecmanError(f"MCP tool {name} returned no text content")

    def connect(self) -> None:
        self._rpc(
            "initialize",
            {
                "protocolVersion": MCP_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {"name": CLIENT_NAME, "version": _client_version()},
    def __init__(self, base_url: str, token: str) -> None:
        if not token:
            raise SecmanIntegrationError("SecMan token must not be empty")
        self._client = httpx.Client(
            base_url=validate_base_url(base_url),
            headers={"Authorization": f"Bearer {token}"},
            verify=_system_ca_context(),
            timeout=_TIMEOUT_SECONDS,
            follow_redirects=False,
            trust_env=False,
        )

    @classmethod
    def login(cls, base_url: str, username: str, REDACTED: str) -> IntegrationClient:
        if not username or not REDACTED:
            raise SecmanIntegrationError("SecMan credentials must not be empty")
        instance = cls.__new__(cls)
        instance._client = httpx.Client(
            base_url=validate_base_url(base_url),
            verify=_system_ca_context(),
            timeout=_TIMEOUT_SECONDS,
            follow_redirects=False,
            trust_env=False,
        )
        try:
            response = instance._client.post(
                "/api/auth/login",
                json={"username": username, "REDACTED": REDACTED},
            )
        except httpx.HTTPError as error:
            instance.close()
            raise SecmanIntegrationError("SecMan login request failed") from error
        if response.status_code not in {200, 204}:
            instance.close()
            raise SecmanIntegrationError(f"SecMan login failed with HTTP {response.status_code}")
        return instance

    def close(self) -> None:
        self._client.close()

    def __enter__(self) -> Self:
        return self

    def __exit__(self, *_: object) -> None:
        self.close()

    def list_subjects(self, scanner_id: int, *, size: int = 100) -> list[IntegrationSubject]:
        if size < 1 or size > 100:
            raise ValueError("subject page size must be between 1 and 100")
        subjects: list[IntegrationSubject] = []
        page = 0
        while True:
            try:
                response = self._client.get(
                    f"/api/integrations/v1/scanners/{scanner_id}/subjects",
                    params={"page": page, "size": size},
                )
            except httpx.HTTPError as error:
                raise SecmanIntegrationError("SecMan subject discovery request failed") from error
            if response.status_code != 200:
                raise SecmanIntegrationError(
                    f"SecMan subject discovery failed with HTTP {response.status_code}"
                )
            try:
                payload = response.json()
                subjects.extend(IntegrationSubject.from_api(row) for row in payload["content"])
                total_pages = int(payload["totalPages"])
            except (KeyError, TypeError, ValueError) as error:
                raise SecmanIntegrationError(
                    "SecMan subject discovery returned an invalid response"
                ) from error
            page += 1
            if page >= total_pages:
                return subjects

    def submit_run(self, body: Mapping[str, Any]) -> dict[str, Any]:
        try:
            response = self._client.post("/api/integrations/v1/runs", json=dict(body))
        except httpx.HTTPError as error:
            raise SecmanIntegrationError("SecMan run submission request failed") from error
        if response.status_code not in {200, 201}:
            raise SecmanIntegrationError(
                f"SecMan run submission failed with HTTP {response.status_code}"
            )
        try:
            payload = response.json()
        except ValueError as error:
            raise SecmanIntegrationError("SecMan run submission returned invalid JSON") from error
        if not isinstance(payload, dict):
            raise SecmanIntegrationError("SecMan run submission returned an invalid response")
        return payload

