        return f"{self.base_url}{self._path}"

    def _rpc(self, method: str, params: dict[str, Any] | None = None) -> Any:
        self._next_id += 1
        body: dict[str, Any] = {"jsonrpc": "2.0", "id": self._next_id, "method": method}
        if params is not None:
            body["params"] = params
        response = self._send("POST", self._path or "/", json=body)
        if response.status_code >= 400:
            raise SecmanError(
                f"MCP {method} failed (HTTP {response.status_code}): {self._detail(response)}"
            )
        payload = self._json(response)
        if not isinstance(payload, dict):
            raise SecmanError(f"MCP {method} returned {str(payload)[:200]}")
        error = payload.get("error")
        if error:
            message = error.get("message") if isinstance(error, dict) else error
            raise SecmanError(f"MCP {method} error: {message}")
        return payload.get("result")

    def _notify(self, method: str, params: dict[str, Any] | None = None) -> None:
        body: dict[str, Any] = {"jsonrpc": "2.0", "method": method}
        if params is not None:
            body["params"] = params
        self._send("POST", self._path or "/", json=body)

    def _call_tool(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        result = self._rpc("tools/call", {"name": name, "arguments": arguments})
        if not isinstance(result, dict):
            raise SecmanError(f"MCP tool {name} returned {str(result)[:200]}")
        if result.get("isError"):
            raise SecmanError(f"MCP tool {name} reported an error: {str(result)[:200]}")
        # SecMan serialises the tool's structured result into a single text block.
        for part in result.get("content") or []:
            if isinstance(part, dict) and part.get("type") == "text":
                try:
                    decoded = json.loads(part.get("text") or "")
                except json.JSONDecodeError as exc:
                    raise SecmanError(
                        f"MCP tool {name} returned unparseable content: {part.get('text', '')[:200]}"
                    ) from exc
                if isinstance(decoded, dict):
                    return decoded
        raise SecmanError(f"MCP tool {name} returned no text content")

    def connect(self) -> None:
        self._rpc(
            "initialize",
            {
                "protocolVersion": MCP_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {"name": CLIENT_NAME, "version": _client_version()},
    def __init__(self, base_url: str, token: str) -> None:
        if not token:
            raise SecmanIntegrationError("SecMan token must not be empty")
        self._client = httpx.Client(
            base_url=validate_base_url(base_url),
            headers={"Authorization": f"Bearer {token}"},
            verify=_system_ca_context(),
            timeout=_TIMEOUT_SECONDS,
            follow_redirects=False,
            trust_env=False,
        )

    @classmethod
    def login(cls, base_url: str, username: str, REDACTED: str) -> IntegrationClient:
        if not username or not REDACTED:
            raise SecmanIntegrationError("SecMan credentials must not be empty")
        instance = cls.__new__(cls)
        instance._client = httpx.Client(
            base_url=validate_base_url(base_url),
            verify=_system_ca_context(),
            timeout=_TIMEOUT_SECONDS,
            follow_redirects=False,
            trust_env=False,
        )
        try:
            response = instance._client.post(
                "/api/auth/login",
                json={"username": username, "REDACTED": REDACTED},
            )
        except httpx.HTTPError as error:
            instance.close()
            raise SecmanIntegrationError("SecMan login request failed") from error
        if response.status_code not in {200, 204}:
            instance.close()
            raise SecmanIntegrationError(f"SecMan login failed with HTTP {response.status_code}")
        return instance

    def close(self) -> None:
        self._client.close()

    def __enter__(self) -> Self:
        return self

    def __exit__(self, *_: object) -> None:
        self.close()

    def list_subjects(self, scanner_id: int, *, size: int = 100) -> list[IntegrationSubject]:
        if size < 1 or size > 100:
            raise ValueError("subject page size must be between 1 and 100")
        subjects: list[IntegrationSubject] = []
        page = 0
        while True:
            try:
                response = self._client.get(
                    f"/api/integrations/v1/scanners/{scanner_id}/subjects",
                    params={"page": page, "size": size},
                )
            except httpx.HTTPError as error:
                raise SecmanIntegrationError("SecMan subject discovery request failed") from error
            if response.status_code != 200:
                raise SecmanIntegrationError(
                    f"SecMan subject discovery failed with HTTP {response.status_code}"
                )
            try:
                payload = response.json()
                subjects.extend(IntegrationSubject.from_api(row) for row in payload["content"])
                total_pages = int(payload["totalPages"])
            except (KeyError, TypeError, ValueError) as error:
                raise SecmanIntegrationError(
                    "SecMan subject discovery returned an invalid response"
                ) from error
            page += 1
            if page >= total_pages:
                return subjects

    def submit_run(self, body: Mapping[str, Any]) -> dict[str, Any]:
        try:
            response = self._client.post("/api/integrations/v1/runs", json=dict(body))
        except httpx.HTTPError as error:
            raise SecmanIntegrationError("SecMan run submission request failed") from error
        if response.status_code not in {200, 201}:
            raise SecmanIntegrationError(
                f"SecMan run submission failed with HTTP {response.status_code}"
            )
        try:
            payload = response.json()
        except ValueError as error:
            raise SecmanIntegrationError("SecMan run submission returned invalid JSON") from error
        if not isinstance(payload, dict):
            raise SecmanIntegrationError("SecMan run submission returned an invalid response")
        return payload

